class DoubleConv(nn.Module):
def __init__(self, in_ch, out_ch):
super().__init__()
self.net = nn.Sequential(
nn.Conv2d(in_ch, out_ch, 3, padding=1),
nn.BatchNorm2d(out_ch),
nn.ReLU(inplace=True),
nn.Conv2d(out_ch, out_ch, 3, padding=1),
nn.BatchNorm2d(out_ch),
nn.ReLU(inplace=True),
)
def forward(self, x):
return self.net(x)
Note
Two convs per stage is the common minimal conv block.

Code: decoder step (Up)
import torch
import torch.nn as nn
class Up(nn.Module):
def __init__(self, in_ch, out_ch):
super().__init__()
self.up = nn.ConvTranspose2d(in_ch, in_ch // 2, 2, stride=2)
self.conv = DoubleConv(in_ch, out_ch)
def forward(self, x, skip):
x = self.up(x)
if skip.shape[-2:] != x.shape[-2:]:
skip = skip[..., : x.size(-2), : x.size(-1)]
x = torch.cat([x, skip], dim=1)
return self.conv(x)
Note
Crop or resize skips to match upsampled tensor before concat.

Code: segmentation head (SegHead)
class SegHead(nn.Module):
def __init__(self, in_ch, n_classes):
super().__init__()
self.proj = nn.Conv2d(in_ch, n_classes, kernel_size=1)
def forward(self, x):
return self.proj(x)
Note
No softmax here if using CrossEntropyLoss.

